     if(ctx == NULL) return 1;
     if(ctx->data == NULL) return 1;
     if(!ctx->valid_state) return SPNG_EBADSTATE;

     int ret, discard;
     unsigned char *data;
     struct spng_chunk chunk;

     chunk.offset = 8;
     chunk.length = 13;
     size_t sizeof_sig_ihdr = 29;

