    //                                                  @:10000
    aor.clear();
    aor.reserve((dropScheme ? 0 : mScheme.size()+1)
        + mUser.size() + mCanonicalHost.size() + 7);
    if(!dropScheme)
    {
       aor += mScheme;
       aor += ':';
    }

    if (!mUser.empty())
    {
 #ifdef HANDLE_CHARACTER_ESCAPING
       {
          oDataStream str(aor);
          mUser.escapeToStream(str, getUserEncodingTable()); 
