       aor += mCanonicalHost;
       aor += Symbols::RS_BRACKET;
    }
    else
    {
       aor += mCanonicalHost;
    }

    if(addPort)
    {
       aor += Symbols::COLON;
       aor += Data(mPort);
    }
 }
