diff --git a/src/hb-ot-glyf-table.hh b/src/hb-ot-glyf-table.hh
index 7b9206c37..a5dd9d680 100644
--- a/src/hb-ot-glyf-table.hh
+++ b/src/hb-ot-glyf-table.hh
@@ -80,1140 +80,1141 @@ struct loca
 struct glyf
 {
   static constexpr hb_tag_t tableTag = HB_OT_TAG_glyf;

   bool sanitize (hb_sanitize_context_t *c HB_UNUSED) const
   {
     TRACE_SANITIZE (this);
     /* Runtime checks as eager sanitizing each glyph is costy */
     return_trace (true);
   }

   template<typename Iterator,
 	   hb_requires (hb_is_source_of (Iterator, unsigned int))>
   static bool
   _add_loca_and_head (hb_subset_plan_t * plan, Iterator padded_offsets)
   {
     unsigned max_offset = + padded_offsets | hb_reduce(hb_add, 0);
     unsigned num_offsets = padded_offsets.len () + 1;
     bool use_short_loca = max_offset < 0x1FFFF;
     unsigned entry_size = use_short_loca ? 2 : 4;
     char *loca_prime_data = (char *) calloc (entry_size, num_offsets);

     if (unlikely (!loca_prime_data)) return false;

     DEBUG_MSG (SUBSET, nullptr, "loca entry_size %d num_offsets %d "
 				"max_offset %d size %d",
 	       entry_size, num_offsets, max_offset, entry_size * num_offsets);

     if (use_short_loca)
       _write_loca (padded_offsets, 1, hb_array ((HBUINT16*) loca_prime_data, num_offsets));
     else
       _write_loca (padded_offsets, 0, hb_array ((HBUINT32*) loca_prime_data, num_offsets));

     hb_blob_t * loca_blob = hb_blob_create (loca_prime_data,
 					    entry_size * num_offsets,
 					    HB_MEMORY_MODE_WRITABLE,
 					    loca_prime_data,
 					    free);

     bool result = plan->add_table (HB_OT_TAG_loca, loca_blob)
 		  && _add_head_and_set_loca_version (plan, use_short_loca);

     hb_blob_destroy (loca_blob);
     return result;
   }

   template<typename IteratorIn, typename IteratorOut,
 	   hb_requires (hb_is_source_of (IteratorIn, unsigned int)),
 	   hb_requires (hb_is_sink_of (IteratorOut, unsigned))>
   static void
   _write_loca (IteratorIn it, unsigned right_shift, IteratorOut dest)
   {
     unsigned int offset = 0;
     dest << 0;
     + it
     | hb_map ([=, &offset] (unsigned int padded_size)
 	      {
 		offset += padded_size;
 		DEBUG_MSG (SUBSET, nullptr, "loca entry offset %d", offset);
 		return offset >> right_shift;
 	      })
     | hb_sink (dest)
     ;
   }

   /* requires source of SubsetGlyph complains the identifier isn't declared */
   template <typename Iterator>
   bool serialize (hb_serialize_context_t *c,
 		  Iterator it,
 		  const hb_subset_plan_t *plan)
   {
     TRACE_SERIALIZE (this);
     unsigned init_len = c->length ();
     for (const auto &_ : it) _.serialize (c, plan);

     /* As a special case when all glyph in the font are empty, add a zero byte
      * to the table, so that OTS doesn’t reject it, and to make the table work
      * on Windows as well.
      * See https://github.com/khaledhosny/ots/issues/52 */
     if (init_len == c->length ())
     {
       HBUINT8 empty_byte;
       empty_byte = 0;
       c->copy (empty_byte);
     }
     return_trace (true);
   }

   /* Byte region(s) per glyph to output
      unpadded, hints removed if so requested
      If we fail to process a glyph we produce an empty (0-length) glyph */
   bool subset (hb_subset_context_t *c) const
   {
     TRACE_SUBSET (this);

     glyf *glyf_prime = c->serializer->start_embed <glyf> ();
     if (unlikely (!c->serializer->check_success (glyf_prime))) return_trace (false);

     hb_vector_t<SubsetGlyph> glyphs;
     _populate_subset_glyphs (c->plan, &glyphs);

     glyf_prime->serialize (c->serializer, hb_iter (glyphs), c->plan);

     auto padded_offsets =
     + hb_iter (glyphs)
     | hb_map (&SubsetGlyph::padded_size)
     ;

     if (c->serializer->in_error ()) return_trace (false);
     return_trace (c->serializer->check_success (_add_loca_and_head (c->plan,
 								    padded_offsets)));
   }

   template <typename SubsetGlyph>
   void
   _populate_subset_glyphs (const hb_subset_plan_t   *plan,
 			   hb_vector_t<SubsetGlyph> *glyphs /* OUT */) const
   {
     OT::glyf::accelerator_t glyf;
     glyf.init (plan->source);

     + hb_range (plan->num_output_glyphs ())
     | hb_map ([&] (hb_codepoint_t new_gid)
 	      {
 		SubsetGlyph subset_glyph = {0};
 		subset_glyph.new_gid = new_gid;

 		/* should never fail: all old gids should be mapped */
 		if (!plan->old_gid_for_new_gid (new_gid, &subset_glyph.old_gid))
 		  return subset_glyph;

 		subset_glyph.source_glyph = glyf.glyph_for_gid (subset_glyph.old_gid, true);
 		if (plan->drop_hints) subset_glyph.drop_hints_bytes ();
 		else subset_glyph.dest_start = subset_glyph.source_glyph.get_bytes ();

 		return subset_glyph;
 	      })
     | hb_sink (glyphs)
     ;

     glyf.fini ();
   }

   static bool
   _add_head_and_set_loca_version (hb_subset_plan_t *plan, bool use_short_loca)
   {
     hb_blob_t *head_blob = hb_sanitize_context_t ().reference_table<head> (plan->source);
     hb_blob_t *head_prime_blob = hb_blob_copy_writable_or_fail (head_blob);
     hb_blob_destroy (head_blob);

     if (unlikely (!head_prime_blob))
       return false;

     head *head_prime = (head *) hb_blob_get_data_writable (head_prime_blob, nullptr);
     head_prime->indexToLocFormat = use_short_loca ? 0 : 1;
     bool success = plan->add_table (HB_OT_TAG_head, head_prime_blob);

     hb_blob_destroy (head_prime_blob);
     return success;
   }

   struct CompositeGlyphChain
   {
     enum composite_glyph_flag_t
     {
       ARG_1_AND_2_ARE_WORDS	= 0x0001,
       ARGS_ARE_XY_VALUES	= 0x0002,
       ROUND_XY_TO_GRID		= 0x0004,
       WE_HAVE_A_SCALE		= 0x0008,
       MORE_COMPONENTS		= 0x0020,
       WE_HAVE_AN_X_AND_Y_SCALE	= 0x0040,
       WE_HAVE_A_TWO_BY_TWO	= 0x0080,
       WE_HAVE_INSTRUCTIONS	= 0x0100,
       USE_MY_METRICS		= 0x0200,
       OVERLAP_COMPOUND		= 0x0400,
       SCALED_COMPONENT_OFFSET	= 0x0800,
       UNSCALED_COMPONENT_OFFSET = 0x1000
     };

     unsigned int get_size () const
     {
       unsigned int size = min_size;
       /* arg1 and 2 are int16 */
       if (flags & ARG_1_AND_2_ARE_WORDS) size += 4;
       /* arg1 and 2 are int8 */
       else size += 2;

       /* One x 16 bit (scale) */
       if (flags & WE_HAVE_A_SCALE) size += 2;
       /* Two x 16 bit (xscale, yscale) */
       else if (flags & WE_HAVE_AN_X_AND_Y_SCALE) size += 4;
       /* Four x 16 bit (xscale, scale01, scale10, yscale) */
       else if (flags & WE_HAVE_A_TWO_BY_TWO) size += 8;

       return size;
     }

     bool is_use_my_metrics () const { return   flags & USE_MY_METRICS; }
     bool is_anchored ()       const { return !(flags & ARGS_ARE_XY_VALUES); }
     void get_anchor_points (unsigned int &point1, unsigned int &point2) const
     {
       const HBUINT8 *p = &StructAfter<const HBUINT8> (glyphIndex);
       if (flags & ARG_1_AND_2_ARE_WORDS)
       {
 	point1 = ((const HBUINT16 *) p)[0];
 	point2 = ((const HBUINT16 *) p)[1];
       }
       else
       {
 	point1 = p[0];
 	point2 = p[1];
       }
     }

     void transform_points (contour_point_vector_t &points) const
     {
       float matrix[4];
       contour_point_t trans;
       if (get_transformation (matrix, trans))
       {
 	if (scaled_offsets ())
 	{
 	  points.translate (trans);
 	  points.transform (matrix);
 	}
 	else
 	{
 	  points.transform (matrix);
 	  points.translate (trans);
 	}
       }
     }

     protected:
     bool scaled_offsets () const
     { return (flags & (SCALED_COMPONENT_OFFSET | UNSCALED_COMPONENT_OFFSET)) == SCALED_COMPONENT_OFFSET; }

     bool get_transformation (float (&matrix)[4], contour_point_t &trans) const
     {
       matrix[0] = matrix[3] = 1.f;
       matrix[1] = matrix[2] = 0.f;

       int tx, ty;
       const HBINT8 *p = &StructAfter<const HBINT8> (glyphIndex);
       if (flags & ARG_1_AND_2_ARE_WORDS)
       {
 	tx = *(const HBINT16 *) p;
 	p += HBINT16::static_size;
 	ty = *(const HBINT16 *) p;
 	p += HBINT16::static_size;
       }
       else
       {
 	tx = *p++;
 	ty = *p++;
       }
       if (is_anchored ()) tx = ty = 0;

       trans.init ((float) tx, (float) ty);

       {
 	const F2DOT14 *points = (const F2DOT14 *) p;
 	if (flags & WE_HAVE_A_SCALE)
 	{
 	  matrix[0] = matrix[3] = points[0].to_float ();
 	  return true;
 	}
 	else if (flags & WE_HAVE_AN_X_AND_Y_SCALE)
 	{
 	  matrix[0] = points[0].to_float ();
 	  matrix[3] = points[1].to_float ();
 	  return true;
 	}
 	else if (flags & WE_HAVE_A_TWO_BY_TWO)
 	{
 	  matrix[0] = points[0].to_float ();
 	  matrix[1] = points[1].to_float ();
 	  matrix[2] = points[2].to_float ();
 	  matrix[3] = points[3].to_float ();
 	  return true;
 	}
       }
       return tx || ty;
     }

     public:
     HBUINT16	flags;
     HBGlyphID	glyphIndex;
     public:
     DEFINE_SIZE_MIN (4);
   };

   struct composite_iter_t : hb_iter_with_fallback_t<composite_iter_t, const CompositeGlyphChain &>
   {
     typedef const CompositeGlyphChain *__item_t__;
     composite_iter_t (hb_bytes_t glyph_, __item_t__ current_) :
       glyph (glyph_), current (current_)
     { if (!check_range (current)) current = nullptr; }
     composite_iter_t () : glyph (hb_bytes_t ()), current (nullptr) {}

     const CompositeGlyphChain &__item__ () const { return *current; }
     bool __more__ () const { return current; }
     void __next__ ()
     {
       if (!(current->flags & CompositeGlyphChain::MORE_COMPONENTS)) { current = nullptr; return; }

       const CompositeGlyphChain *possible = &StructAfter<CompositeGlyphChain,
 							 CompositeGlyphChain> (*current);
       if (!check_range (possible)) { current = nullptr; return; }
       current = possible;
     }
     bool operator != (const composite_iter_t& o) const
     { return glyph != o.glyph || current != o.current; }

     bool check_range (const CompositeGlyphChain *composite) const
     {
       return glyph.check_range (composite, CompositeGlyphChain::min_size)
 	  && glyph.check_range (composite, composite->get_size ());

