   INIT_DISPATCH {
     CASE(OP_NOP, Z) {
       /* do nothing */
       NEXT;
     }

     CASE(OP_MOVE, BB) {
       regs[a] = regs[b];
       NEXT;
     }

     CASE(OP_LOADL, BB) {
       switch (pool[b].tt) {   /* number */
       case IREP_TT_INT32:
         regs[a] = mrb_int_value(mrb, (mrb_int)pool[b].u.i32);
         break;
       case IREP_TT_INT64:
 #if defined(MRB_INT64)
         regs[a] = mrb_int_value(mrb, (mrb_int)pool[b].u.i64);
         break;
 #else
 #if defined(MRB_64BIT)
         if (INT32_MIN <= pool[b].u.i64 && pool[b].u.i64 <= INT32_MAX) {
           regs[a] = mrb_int_value(mrb, (mrb_int)pool[b].u.i64);
           break;
         }
 #endif
         goto L_INT_OVERFLOW;
 #endif
       case IREP_TT_BIGINT:
         goto L_INT_OVERFLOW;
 #ifndef MRB_NO_FLOAT
       case IREP_TT_FLOAT:
         regs[a] = mrb_float_value(mrb, pool[b].u.f);
         break;
 #endif
       default:
