       CHECKPOINT_END(RBREAK_TAG_JUMP);

       mrb->exc = NULL; /* clear break object */
       pc = irep->iseq + a;
       JUMP;
     }

     CASE(OP_EXCEPT, B) {
       mrb_value exc;

       if (mrb->exc == NULL) {
         exc = mrb_nil_value();
       }
       else {
         switch (mrb->exc->tt) {
