 static char *stb__splitpath_raw(char *buffer, char *path, int flag)
 {
    ptrdiff_t len=0,x,y, n = (int) strlen(path), f1,f2;
    char *s = stb_strrchr2(path, '/', '\\');
    char *t = strrchr(path, '.');
