   Status initialized_ = true;
   size_t image_xsize_;
   size_t image_ysize_;
   std::vector<PatchBlending> blending_info_;
   const std::vector<ExtraChannelInfo>* extra_channel_info_;
   std::vector<float> zeroes_;
